import { MakeLogicType, connect, kea, path, props, selectors } from 'kea'

import { Scene } from 'scenes/sceneTypes'
import { urls } from 'scenes/urls'

import { FileSystemIconType } from '~/queries/schema/schema-general'
import { Breadcrumb } from '~/types'

import { messageTemplateLogic } from './messageTemplateLogic'

export interface MessageTemplateSceneLogicProps {
    id: string
    messageId?: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface messageTemplateSceneLogicValues {
    isTransactional: boolean // messageTemplateLogic
    breadcrumbs: Breadcrumb[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface messageTemplateSceneLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        breadcrumbs: (id: string, isTransactional: boolean) => Breadcrumb[]
    }
}

export type messageTemplateSceneLogicType = MakeLogicType<
    messageTemplateSceneLogicValues,
    {},
    MessageTemplateSceneLogicProps,
    messageTemplateSceneLogicMeta
>

export const messageTemplateSceneLogic = kea<messageTemplateSceneLogicType>([
    path(['products', 'workflows', 'frontend', 'messageTemplateSceneLogic']),
    props({} as MessageTemplateSceneLogicProps),
    connect((props: MessageTemplateSceneLogicProps) => ({
        values: [messageTemplateLogic(props), ['isTransactional']],
    })),
    selectors({
        breadcrumbs: [
            (s, p) => [p.id, s.isTransactional],
            (id: string, isTransactional: boolean): Breadcrumb[] => {
                return [
                    isTransactional
                        ? {
                              key: Scene.Transactional,
                              name: 'Transactional',
                              path: urls.transactional(),
                              iconType: 'transactional',
                          }
                        : {
                              key: [Scene.Workflows, 'library'],
                              name: 'Library',
                              path: urls.workflows('library'),
                              iconType: 'workflows',
                          },
                    ...(id === 'new'
                        ? [
                              {
                                  key: 'new-template',
                                  name: isTransactional ? 'New transactional email' : 'New template',
                                  path: urls.workflowsLibraryTemplateNew(),
                                  iconType: 'workflows' as FileSystemIconType,
                              },
                          ]
                        : [
                              {
                                  key: 'edit-template',
                                  name: isTransactional ? 'Manage transactional email' : 'Manage template',
                                  path: urls.workflowsLibraryTemplate(id),
                                  iconType: 'workflows' as FileSystemIconType,
                              },
                          ]),
                ]
            },
        ],
    }),
])
